import math

phase = 0
pts_left = []
pts_right = []
targets = []

def to_xy(origin, b_deg, d_m):
    b = math.radians(b_deg)
    return (round(origin[0] + d_m * math.cos(b), 2), round(origin[1] + d_m * math.sin(b), 2))

def control(obs):
    global phase, pts_left, pts_right, targets
    head = obs['head']
    views = obs.get('views', {})

    if phase == 0:
        if head['settled'] and abs(head['gaze_deg'] - 165) < 5:
            dv = views.get('direct', {})
            orig = dv.get('origin', [0.1, 0.0])
            for b, d in dv.get('walls', []):
                pts_left.append((b, d, to_xy(orig, b, d)))
            for b, d in dv.get('target_corners', []):
                targets.append(('L', b, d, to_xy(orig, b, d)))
            phase = 1
            return (0.0, 0.0, -165.0)
        return (0.0, 0.0, 165.0)
    elif phase == 1:
        if head['settled'] and abs(head['gaze_deg'] - (-165)) < 5:
            dv = views.get('direct', {})
            orig = dv.get('origin', [0.1, 0.0])
            for b, d in dv.get('walls', []):
                pts_right.append((b, d, to_xy(orig, b, d)))
            for b, d in dv.get('target_corners', []):
                targets.append(('R', b, d, to_xy(orig, b, d)))
            print('LEFT_VIEW:', sorted(pts_left, key=lambda x: x[0]))
            print('RIGHT_VIEW:', sorted(pts_right, key=lambda x: x[0]))
            print('TARGETS:', targets)
            print('TARGET_LOS:', obs.get('target'))
            phase = 2
            wake('scan_complete')
            return (0.0, 0.0, -165.0)
        return (0.0, 0.0, -165.0)
    return (0.0, 0.0, -165.0)

