import math

def control(obs):
    if obs['counters']['commands'] <= 1 and obs['t'] < 1.0:
        print('RIG:', obs['rig'])
    cam = obs.get('views', {}).get('camera')
    if cam:
        print(f"t={obs['t']:.1f} prog={obs['progress']['covered']:.1f} hitch={obs['hitch_deg']:.1f} walls={len(cam['walls'])} corners={cam.get('target_corners')}")
        if cam['walls']:
            pts = []
            ox, oy = cam['origin']
            for b, d in cam['walls'][::max(1, len(cam['walls'])//10)]:
                rad = math.radians(b)
                pts.append((round(ox + d*math.cos(rad), 1), round(oy + d*math.sin(rad), 1)))
            print('  cam_pts:', pts)
    hitch = obs['hitch_deg']
    steer = max(-42.0, min(42.0, 2.0 * hitch))
    return (steer, -1.0, -41.0)

